+    let response = responses_call(
+        &app,
+        json!({
+            "model": "Qwen/Qwen1.5-0.5B-Chat",
+            "input": "hello",
+            "background": true
+        }),
+    )
+    .await;
+    assert_eq!(response.status(), StatusCode::BAD_REQUEST);
+    let body = to_bytes(response.into_body(), usize::MAX).await.expect("read body");
+    let json: serde_json::Value = serde_json::from_slice(&body).expect("decode json");
+    assert_eq!(json["error"]["param"], "background");
+
+    // previous_response_id cannot be resolved without a store; unknown IDs
+    // fail like every other unknown response ID.
+    let response = responses_call(
+        &app,
+        json!({
+            "model": "Qwen/Qwen1.5-0.5B-Chat",
+            "input": "hello",
+            "previous_response_id": "resp_missing"
+        }),
+    )
+    .await;
+    assert_eq!(response.status(), StatusCode::NOT_FOUND);
+    let body = to_bytes(response.into_body(), usize::MAX).await.expect("read body");
+    let json: serde_json::Value = serde_json::from_slice(&body).expect("decode json");
+    assert_eq!(
+        json["error"]["message"],
+        "Response with id 'resp_missing' not found."
+    );
+    assert_eq!(json["error"]["type"], "NotFoundError");
+    assert_eq!(json["error"]["code"], 404);
+
+    // Retrieval and cancellation of never-stored responses are 404.
+    for (method, uri) in [
+        ("GET", "/v1/responses/resp_missing"),
+        ("POST", "/v1/responses/resp_missing/cancel"),
+    ] {
+        let response = app
+            .clone()
+            .call(
+                Request::builder()
+                    .method(method)
+                    .uri(uri)
+                    .body(Body::empty())
+                    .expect("build request"),
+            )
+            .await
+            .expect("call app");
+        assert_eq!(response.status(), StatusCode::NOT_FOUND, "{method} {uri}");
+    }
+
+    // Built-in tool types are rejected: only function tools are supported.
+    let response = responses_call(
+        &app,
+        json!({
+            "model": "Qwen/Qwen1.5-0.5B-Chat",
+            "input": "hello",
+            "tools": [{"type": "web_search_preview"}]
+        }),
+    )
+    .await;
+    assert_eq!(response.status(), StatusCode::BAD_REQUEST);
+    let body = to_bytes(response.into_body(), usize::MAX).await.expect("read body");
+    let json: serde_json::Value = serde_json::from_slice(&body).expect("decode json");
+    let message = json["error"]["message"].as_str().expect("error message");
+    assert!(
+        message.contains("tools[0]") && message.contains("web_search_preview"),
+        "{message}"
+    );
+
+    // store=true executes normally (store-off Python parity).
+    let json = responses_stream_terminal(
+        &app,
+        json!({
+            "model": "Qwen/Qwen1.5-0.5B-Chat",
+            "input": "hello",
+            "store": true
+        }),
+    )
+    .await;
+    engine_task.await.expect("mock engine task");
+    assert_eq!(json["status"], "completed");
+}

